  }
  func snap(_ name: String) async {
    let wv = ctrl.view as! WKWebView
    guard let img = try? await wv.takeSnapshot(configuration: nil) else { print("snap failed"); return }
    let rep = NSBitmapImageRep(data: img.tiffRepresentation!)!
    try! rep.representation(using: .png, properties: [:])!.write(to: URL(fileURLWithPath: "/tmp/bogeyharness/\(name).png"))
  }
